WITH valid AS (SELECT id, order_id, method, paid_at, CASE WHEN method IN ('bank_transfer', 'cash') THEN 'Priority' ELSE 'Other' END AS method_group FROM payments WHERE paid_at > DATE '2024-02-18'), enriched AS (SELECT *, FIRST_VALUE(method, TRUE) OVER (PARTITION BY order_id, method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method, FIRST_VALUE(method) IGNORE NULLS OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_method_2, ROW_NUMBER() OVER (PARTITION BY method ORDER BY paid_at DESC, id) AS seq_no FROM valid), with_dims AS (SELECT src.*, o.discount, o.order_date FROM enriched src LEFT JOIN orders o ON src.order_id = o.id) SELECT order_id, seq_no, DATE_TRUNC('YEAR', paid_at) AS year_start, MAX(paid_at) AS last_seen, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN method = 'card' THEN 1 END), 0), 2) AS discount_per_card, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, PERCENT_RANK() OVER (PARTITION BY order_id ORDER BY (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 DESC) AS duration_min_percent_rank FROM with_dims GROUP BY order_id, seq_no, DATE_TRUNC('YEAR', paid_at) ORDER BY order_id NULLS LAST
